CREATE TABLE IF NOT EXISTS `NewsResponseItem` (`author` TEXT NOT NULL, `date` TEXT NOT NULL, `description` TEXT NOT NULL, `link` TEXT NOT NULL, `title` TEXT NOT NULL, PRIMARY KEY(`link`));
CREATE TABLE IF NOT EXISTS `MatchPreviewInfo` (`id` TEXT NOT NULL, `event` TEXT NOT NULL, `series` TEXT NOT NULL, `status` TEXT NOT NULL, `team1` TEXT NOT NULL, `team2` TEXT NOT NULL, `time` TEXT, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `MatchInfo` (`id` TEXT NOT NULL, `event` TEXT NOT NULL, `head2head` TEXT NOT NULL, `note` TEXT NOT NULL, `score` TEXT NOT NULL, `teams` TEXT NOT NULL, `bans` TEXT NOT NULL, `videos` TEXT NOT NULL, `matchData` TEXT NOT NULL, `mapCount` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `TournamentPreview` (`dates` TEXT NOT NULL, `id` TEXT NOT NULL, `img` TEXT NOT NULL, `location` TEXT NOT NULL, `prize` TEXT NOT NULL, `status` TEXT NOT NULL, `title` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `TournamentDetails` (`id` TEXT NOT NULL, `bracket` TEXT NOT NULL, `dates` TEXT NOT NULL, `img` TEXT NOT NULL, `location` TEXT NOT NULL, `matches` TEXT NOT NULL, `participants` TEXT NOT NULL, `prize` TEXT NOT NULL, `prizes` TEXT NOT NULL, `subtitle` TEXT NOT NULL, `title` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `TopicTracker` (`topic` TEXT NOT NULL, PRIMARY KEY(`topic`));
CREATE TABLE IF NOT EXISTS `TeamDetails` (`id` TEXT NOT NULL, `country` TEXT NOT NULL, `img` TEXT NOT NULL, `name` TEXT NOT NULL, `rank` INTEGER NOT NULL, `region` TEXT NOT NULL, `roster` TEXT NOT NULL, `tag` TEXT, `twitter` TEXT, `upcoming` TEXT NOT NULL, `completed` TEXT NOT NULL, `website` TEXT, `points` INTEGER, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
